8	/** The Sphinx card: "1 point. 2 per type beyond three, else 1." */
9	const BASE_POINTS = 1;
10	/** Each Sphinx surveys the types around it — every card but itself. */
11	const FREE_TYPES = 3;
12	const POINTS_PER_TYPE_BEYOND_FREE = 2;
13	const POINTS_WITHIN_FREE_TYPES = 1;
14	
15	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
16	
17	const countDistinctTypes = (army: Card[]): number =>
18	  new Set(army.map((card) => card.monster)).size;
19	
20	const typeBonus = (distinctTypes: number): number =>
21	  distinctTypes > FREE_TYPES
22	    ? POINTS_PER_TYPE_BEYOND_FREE * (distinctTypes - FREE_TYPES)
23	    : POINTS_WITHIN_FREE_TYPES;
24	
