26	  army.reduce((total, card, index) => {
27	    if (!isSphinx(card)) return total;
28	    const otherCards = army.filter((_, other) => other !== index);
29	    return total + BASE_POINTS + typeBonus(countDistinctTypes(otherCards));
30	  }, 0);
